/**
 * Session admission guards. Pure: the Session object gathers the facts (chain cost, its own start
 * history) and asks these functions for a verdict. Loops are stopped by the chain limits (hop depth,
 * chain spend); floods of non-user wakes by the session start rate.
 */
import { LIMITS, type WakeEvent } from '../../../contracts/index.js';

export type GuardVerdict =
  | { kind: 'ok' }
  | { kind: 'drop'; reason: string; notice?: string }
  | { kind: 'defer'; untilMs: number; reason: string };

/** Events generated by another agent (not the user, not the system). */
const isAgentOriginated = (e: Pick<WakeEvent, 'origin' | 'kind'>): boolean =>
  e.origin.type === 'agent' || e.kind === 'agent_message';

/** Chain: hop depth past LIMITS.chain.maxHopDepth is dropped. */
export function checkHop(event: WakeEvent, maxHopDepth: number = LIMITS.chain.maxHopDepth): GuardVerdict {
  const depth = event.hop?.depth ?? 0;
  if (depth <= maxHopDepth) return { kind: 'ok' };
  return {
    kind: 'drop',
    reason: 'hop_limit',
    notice: `Stopped an agent-to-agent message chain after ${maxHopDepth} hops to prevent a loop. Send a new message to continue.`,
  };
}

/** Chain: agent-originated wakes stop once the chain's spend reaches LIMITS.chain.maxCostUsd. */
export function checkPeerCost(event: WakeEvent, chainCostUsd: number, maxCostUsd: number = LIMITS.chain.maxCostUsd): GuardVerdict {
  if (!event.hop || !isAgentOriginated(event) || chainCostUsd < maxCostUsd) return { kind: 'ok' };
  return {
    kind: 'drop',
    reason: 'peer_cost_cap',
    notice: `Stopped agent-to-agent work: this conversation chain reached its $${maxCostUsd.toFixed(2)} budget.`,
  };
}

/**
 * Session: non-user wakes may start at most LIMITS.session.maxAutoStartsPerMinute runs; the rest are
 * deferred until the window opens. User messages are never rate limited. `recentStarts` = run start times (ms).
 */
export function checkRate(
  event: WakeEvent,
  facts: { now: number; recentStarts: readonly number[] },
  maxPerMinute: number = LIMITS.session.maxAutoStartsPerMinute,
): GuardVerdict {
  if (event.priority === 'user' || event.origin.type === 'user') return { kind: 'ok' };
  const window = facts.recentStarts.filter((t) => facts.now - t < 60_000).sort((a, b) => a - b);
  if (window.length < maxPerMinute) return { kind: 'ok' };
  const oldest = window[window.length - maxPerMinute] ?? facts.now;
  return { kind: 'defer', untilMs: oldest + 60_000, reason: 'flood_cap' };
}
